current.custom_css:
.m-newsletter-form__wrapper {
--color-border: 0,0,0;
}
.m-custom-hero .m-hero__content .m-hero__text {
  color: var(--color-sub-text);
}
.m-menu .m-menu__item .m-menu__link--main {
  font-size: 14px;
  font-weight: 700;
}
.m-custom-slideshow .m-slide__content .m-slide__subtitle {
  font-weight: 800;
  font-size: 14px;
  margin-bottom: 10px;
  letter-spacing: 1px;
}

.m-custom-collection-list .m-collection-card__info .m-collection-card__title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: 0.5px;
}
.m-custom-hero .m-hero__title {
  font-weight: 700;
  letter-spacing: 2px;
}

.m-custom-hero .m-hero__text {
  margin-bottom: 36px;
}

.m-product-card .m-product-card__title .m-product-card__name {
  font-weight: 700;
  font-size: 14px;
}
.m-custom-content-section .m-section-py {
  border-top: 1px solid #eeeeee;
}
[data-section-type="icon-box"] .m\:column:nth-child(2) .m-icon-box {
  border-width: 0 1px 0 1px;
  border-style: solid;
  border-color: #eeeeee;
}
[data-section-type="icon-box"] .m-icon-box__content h3 {
  font-size: 16px;
  line-height: 23px;
  margin-bottom: 10px;
  letter-spacing: 0.5px;
}
.m-footer .m-footer--block .m-footer--block-title {
  letter-spacing: 1px;
  font-weight: 700;
  font-size: 14px;
}

@media (min-width: 1024px) {
  .m-footer--bottom-inner {
    border-top: 1px solid #e0e0e0;
  }
}
@media (min-width: 1280px) {
  .m-footer--block-newsletter {
    padding-right: 134px;
  }
  .m-footer--block-newsletter .m-footer--block-title {
    font-size: 24px;
  }
}

@media (min-width: 768px) {
  .m-custom-hero .m-hero__content .m-hero__title {
    font-size: 36px;
    margin-bottom: 20px;
  }
}
